var p=UnityEngine.Object.FindFirstObjectByType<ChooGuard.App.Fps.FirstPersonResponder>();var c=p.GetComponent<UnityEngine.CharacterController>();var direction=new UnityEngine.Vector3(.34734274f,0,.93773824f);var feet=p.transform.position;var hits=UnityEngine.Physics.CapsuleCastAll(feet+UnityEngine.Vector3.up*(c.radius+.03f),feet+UnityEngine.Vector3.up*(c.height-c.radius-.03f),c.radius-.01f,direction,2f,~0,UnityEngine.QueryTriggerInteraction.Ignore);var rows=new System.Collections.Generic.List<object>();System.Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));foreach(var h in hits){if(h.collider.transform.IsChildOf(p.transform))continue;var name=h.collider.name;var mesh=h.collider as UnityEngine.MeshCollider;rows.Add(new{name,distance=h.distance,point=h.point.ToString("F4"),normal=h.normal.ToString("F4"),triangle=h.triangleIndex,mesh=mesh!=null?mesh.sharedMesh.name:"none"});if(rows.Count>=8)break;}return new{feet=feet.ToString("F4"),hits=rows};